(function () {
  'use strict';
  const chunkSet = {"title":"Text Evidence","topic":"Reading Comprehension","questions":[{"id":"reading-comprehension-text-evidence-q0001","version":3,"contentHash":"sha256:6745d2655ac6c0506e15dc457a0ac3353e58453cd9e8def7c99e8a577311ce4c","question":"Read the passage. Grade 2 foundation passage: A class kept a school garden healthy. Students watered the seedlings each morning and recorded how tall they grew. They also moved the shade cloth when the afternoon sun became too strong.\n\nWhich sentence from the passage best supports this idea: The students used observations to care for the plants.","choices":["The art room displayed clay bowls near the window.","They recorded how tall the seedlings grew.","The passage says every reader already knew about school garden.","The title names the topic but gives no proof."],"correct":1,"studyAid":{"definition":"Supporting evidence consists of specific facts, actions, or details from the text that prove a main idea is true.","example":"Main idea: 'My dog is hungry.' Supporting evidence: 'He barked at his empty bowl and nudged my leg with his nose.'","strategyClue":"Look for a sentence that shows the students actively watching, measuring, or tracking the plants' progress. An observation requires looking at something to learn information.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They recorded how tall the seedlings grew. To record how tall a plant is growing, a student must look closely at it. This act of recording the growth is a direct example of using observations to care for the plants.","incorrect":[{"choice":"The art room displayed clay bowls near the window.","category":"unrelated topic","reason":"This sentence describes art supplies, not the school garden. It does not mention the plants or the students' actions in the garden."},"",{"choice":"The passage says every reader already knew about school garden.","category":"not in text","reason":"This statement is not found in the passage provided. Even if it were, it does not describe an action taken to observe or care for the plants."},{"choice":"The title names the topic but gives no proof.","category":"missing supporting evidence","reason":"Titles provide a general idea but do not count as proof or observational actions taken by the students to care for the garden."}]},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":1,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0002","version":3,"contentHash":"sha256:c3648af92a727416767f5a696d4692edfd2d18adae4ee7a07e1aa50755a1e09f","question":"Read the passage. Grade 2 foundation passage: Student volunteers made the library easier to use. They sorted returned books by call number before placing them on shelves. They made bright shelf labels for mystery, science, and biography books.\n\nWhich detail is the strongest evidence for the answer, \"The volunteers helped readers find materials more efficiently.\"?","choices":["The passage says every reader already knew about library helpers.","The cafeteria served tomato soup on Thursday.","They sorted returned books by call number before placing them on shelves.","The title names the topic but gives no proof."],"correct":2,"studyAid":{"definition":"Strong evidence is a specific fact or detail from the text that directly supports a claim or an answer.","example":"Claim: The dog is energetic. Evidence: The dog ran in circles and jumped over the couch.","strategyClue":"Look for an action in the text that directly explains how the library became 'easier to use.' Ignore details that are unrelated to the library or do not explain the benefit to the reader.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They sorted returned books by call number before placing them on shelves. Organizing books by call number is a specific system designed to help users locate books quickly and accurately.","incorrect":[{"choice":"The passage says every reader already knew about library helpers.","category":"not supported by text","reason":"This information does not appear in the text provided. Evidence must come directly from the passage, not from outside assumptions."},{"choice":"The cafeteria served tomato soup on Thursday.","category":"irrelevant information","reason":"This detail is completely unrelated to the library or the task of helping readers. Always look for evidence that directly addresses the specific claim in the question."},"",{"choice":"The title names the topic but gives no proof.","category":"incorrect evidence type","reason":"A title might introduce a topic, but it does not describe the specific actions volunteers took to make the library easier to use. You need a sentence that shows an action being performed."}]},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":2,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0003","version":3,"contentHash":"sha256:71153ea6e93291462c7213422cd85eaba9b0dc82a8a7dbcc7b86c358d1bc69bf","question":"Read the passage. Grade 2 foundation passage: A science club collected rainwater for outdoor plants. The barrel caught water from the roof during storms. Members used the stored water on dry afternoons instead of turning on the hose.\n\nWhich sentence from the passage best supports this idea: The rain barrel reduced the need for hose water.","choices":["The title names the topic but gives no proof.","A soccer team practiced corner kicks after school.","The passage says every reader already knew about rain barrel.","Members used the stored water on dry afternoons instead of turning on the hose."],"correct":3,"studyAid":{"definition":"Supporting evidence consists of specific facts or details from the text that explain 'how' or 'why' a main idea is true.","example":"Main idea: 'Dogs are helpful pets.' Evidence: 'My dog helps me find my lost keys every morning.'","strategyClue":"Look for the sentence that describes a specific action taken by the club members to avoid using the hose. Ask yourself, 'Which sentence shows the barrel replacing the hose?'","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Members used the stored water on dry afternoons instead of turning on the hose. This sentence directly shows how the barrel provided an alternative to the hose, proving it reduced the need for one.","incorrect":[{"choice":"The title names the topic but gives no proof.","category":"not a passage sentence","reason":"This is not a sentence found in the text, and it does not explain how the barrel helps save water."},{"choice":"A soccer team practiced corner kicks after school.","category":"irrelevant information","reason":"This sentence is not in the passage and has nothing to do with rainwater or gardening."},{"choice":"The passage says every reader already knew about rain barrel.","category":"unsupported claim","reason":"This is not a sentence from the passage and does not provide evidence about how the barrel reduces water usage."},""]},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":3,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0004","version":3,"contentHash":"sha256:a6ba56c2cb10bc4757c86e5e572cb237b9dc4f6788c79775b4a57a4da5e25f2e","question":"Read the passage. Grade 2 foundation passage: Young reporters created a newspaper for their school. They interviewed teachers, wrote short articles, and checked facts before printing. The first issue included a sports column, a book review, and a lunch survey.\n\nWhich detail is the strongest evidence for the answer, \"The reporters tried to make the newspaper accurate.\"?","choices":["They interviewed teachers, wrote short articles, and checked facts before printing.","The playground slide was painted blue over spring break.","The passage says every reader already knew about class newspaper.","The title names the topic but gives no proof."],"correct":0,"studyAid":{"definition":"To find evidence for a statement, look for specific actions or descriptions in the text that directly support or prove that statement true.","example":"Statement: 'The dog was hungry.' Evidence: 'The dog whimpered and nudged his empty food bowl.'","strategyClue":"Look at the keyword in the question—'accurate'—and scan the text for actions related to verifying information, checking, or research.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They interviewed teachers, wrote short articles, and checked facts before printing. Checking facts is the direct action that ensures the information in a newspaper is truthful and correct.","incorrect":["",{"choice":"The playground slide was painted blue over spring break.","category":"irrelevant information","reason":"This detail describes school property, not the quality or accuracy of the newspaper's writing."},{"choice":"The passage says every reader already knew about class newspaper.","category":"inaccurate text evidence","reason":"The passage does not state that readers already knew about the newspaper, and knowing about a topic is different from ensuring information is accurate."},{"choice":"The title names the topic but gives no proof.","category":"lacks supporting evidence","reason":"Titles often introduce a topic, but they do not provide the specific actions taken by the authors to ensure their writing is factual."}]},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":4,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0005","version":3,"contentHash":"sha256:f836583db16a78d672d3f727e2922ece96499560d3df767d65612981a011f180","question":"Read the passage. Grade 2 foundation passage: Families removed litter from the beach. They filled ten bags with plastic wrappers, bottle caps, and broken fishing line. Afterward, volunteers posted signs reminding visitors to pack out trash.\n\nWhich sentence from the passage best supports this idea: The cleanup made the beach safer for wildlife.","choices":["The town band played a concert in the park.","They filled ten bags with plastic wrappers, bottle caps, and broken fishing line.","The passage says every reader already knew about beach cleanup.","The title names the topic but gives no proof."],"correct":1,"studyAid":{"definition":"Supporting evidence is information from the text that proves an idea is true or correct.","example":"Idea: The puppy was hungry. Evidence: He whined and scratched at his empty food bowl.","strategyClue":"Look for a sentence that shows an action being performed. Ask yourself, 'Does this action directly help solve the problem mentioned in the prompt?'","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They filled ten bags with plastic wrappers, bottle caps, and broken fishing line. This sentence provides evidence of the cleanup, explaining that removing harmful items like broken fishing line and plastic reduces the risk of injury to animals.","incorrect":[{"choice":"The town band played a concert in the park.","category":"irrelevant information","reason":"This sentence describes a musical event that has no connection to beach cleanup or protecting wildlife."},"",{"choice":"The passage says every reader already knew about beach cleanup.","category":"unsupported claim","reason":"The passage never mentions what the readers already knew; this is an opinion, not evidence found in the text."},{"choice":"The title names the topic but gives no proof.","category":"missing evidence","reason":"The title only introduces the subject; it cannot act as evidence because it does not describe any actions taken to help the beach."}]},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":5,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0006","version":3,"contentHash":"sha256:027849709cdc50846ac4aa9338a5e5c97dcc31279bc77ce55720e86090293390","question":"Read the passage. Grade 2 foundation passage: A safety officer taught students how to ride bikes safely. She showed how helmets should sit flat and snug on a rider's head. She reminded riders to signal turns and watch for opening car doors.\n\nWhich detail is the strongest evidence for the answer, \"A helmet must fit correctly to protect a rider.\"?","choices":["The passage says every reader already knew about bike safety.","The school choir rehearsed a song about the moon.","She showed how helmets should sit flat and snug on a rider's head.","The title names the topic but gives no proof."],"correct":2,"studyAid":{"definition":"Strong evidence is a specific sentence or fact from the text that directly explains or proves your answer.","example":"Claim: Dogs are helpful pets. Evidence: They can be trained to assist people who cannot see.","strategyClue":"Highlight the claim you are trying to support. Then, scan the passage specifically for words related to that claim, such as 'helmet' or 'fit', and ignore sentences about other topics.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: She showed how helmets should sit flat and snug on a rider's head. This sentence directly describes the proper positioning and fit of a helmet, which supports the idea that correct fit is a requirement for safety.","incorrect":[{"choice":"The passage says every reader already knew about bike safety.","category":"unsupported by passage","reason":"The text does not state what the readers already knew. This detail is not found in the passage and does not explain why a helmet needs to fit correctly."},{"choice":"The school choir rehearsed a song about the moon.","category":"irrelevant information","reason":"This detail is completely unrelated to the topic of bike safety or helmets. It does not provide evidence for how a helmet protects a rider."},"",{"choice":"The title names the topic but gives no proof.","category":"misidentifying evidence","reason":"Even if a title were present, it would be a label, not evidence. Evidence must be a fact or description from the body of the text that proves the specific claim about helmet fit."}]},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":6,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0007","version":3,"contentHash":"sha256:463309f5dbf855084db195117f5881d1d13fa2b696fe21e203bc0e9cdfc04d8a","question":"Read the passage. Grade 2 foundation passage: Transportation planners added bus routes near busy neighborhoods. The new route stopped near the clinic, grocery store, and community center. Riders waited less time because buses arrived every fifteen minutes.\n\nWhich sentence from the passage best supports this idea: The new bus route served community needs.","choices":["The title names the topic but gives no proof.","A bakery sold cinnamon rolls before sunrise.","The passage says every reader already knew about city buses.","The new route stopped near the clinic, grocery store, and community center."],"correct":3,"studyAid":{"definition":"Supporting evidence is a detail from the text that proves a specific claim or main idea is true.","example":"Claim: The park is fun. Supporting evidence: The park has a new playground and a pond for feeding ducks.","strategyClue":"Look for words in the options that describe specific community services or locations, then check if those words appear in the passage as proof of the route's purpose.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: The new route stopped near the clinic, grocery store, and community center. This sentence provides evidence because it lists specific locations that people in a community rely on every day, proving the bus route is useful for residents.","incorrect":[{"choice":"The title names the topic but gives no proof.","category":"not in text","reason":"This sentence is not part of the passage provided. Even if it were, a title only identifies the subject; it does not list the specific places or services that show how needs are being met."},{"choice":"A bakery sold cinnamon rolls before sunrise.","category":"irrelevant information","reason":"This information is not mentioned in the passage and does not help explain how a bus route assists the community."},{"choice":"The passage says every reader already knew about city buses.","category":"inaccurate claim","reason":"The passage never mentions what readers know. Evidence must be based on facts explicitly stated in the text, not on assumptions about the reader's knowledge."},""]},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":7,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0008","version":3,"contentHash":"sha256:1626901af13f380c9bbdd907defa29fe00fab4e58e67af8936f7fbab6f175550","question":"Read the passage. Grade 2 foundation passage: Cast members prepared a play through teamwork. Actors practiced lines while stage crew members painted scenery and tested lights. When a curtain rope tangled, two students fixed it before rehearsal began.\n\nWhich detail is the strongest evidence for the answer, \"The production required more than acting.\"?","choices":["Actors practiced lines while stage crew members painted scenery and tested lights.","A math poster showed different kinds of triangles.","The passage says every reader already knew about school play.","The title names the topic but gives no proof."],"correct":0,"studyAid":{"definition":"Supporting evidence is a specific fact or detail from the text that directly proves an idea or answer.","example":"Claim: 'The character was tired.' Evidence: 'She rubbed her eyes and yawned loudly.' (Instead of 'She went to school.')","strategyClue":"Look for a sentence that describes a task, role, or action that is different from acting. Identify which option shows someone working behind the scenes.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Actors practiced lines while stage crew members painted scenery and tested lights. This sentence explicitly mentions the 'stage crew' doing tasks like painting scenery and testing lights, which proves that the production involved more than just the actors speaking lines.","incorrect":["",{"choice":"A math poster showed different kinds of triangles.","category":"irrelevant information","reason":"This detail is about math, which is completely unrelated to the production of a play and does not provide evidence for what the production required."},{"choice":"The passage says every reader already knew about school play.","category":"unsupported claim","reason":"The passage does not state that every reader knew about the school play; this choice is not found in the text and does not support the idea that the production required more than acting."},{"choice":"The title names the topic but gives no proof.","category":"meta-analysis error","reason":"While a title identifies the topic, it acts as a label rather than evidence. The question asks for a specific detail from the passage that proves the statement."}]},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":8,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0009","version":3,"contentHash":"sha256:a08992a3a2649bbe34563937ef726e671f5e7e9b95c1404ff31225fffb08eb72","question":"Read the passage. Grade 2 foundation passage: Cafeteria workers turned food scraps into compost. Fruit peels and vegetable ends went into a covered bin behind the cafeteria. After several weeks, the dark compost was mixed into flower beds.\n\nWhich sentence from the passage best supports this idea: Food scraps can become useful instead of being thrown away.","choices":["A new scoreboard was installed in the gym.","After several weeks, the dark compost was mixed into flower beds.","The passage says every reader already knew about compost bin.","The title names the topic but gives no proof."],"correct":1,"studyAid":{"definition":"To support an idea, look for a sentence that provides direct evidence or a specific example of that idea happening in the text.","example":"Idea: Dogs are helpful. Evidence: The dog barked to warn us that a stranger was at the door.","strategyClue":"First, identify the main claim in the question. Then, look through each sentence and ask, 'Does this sentence show the claim actually happening?'","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: After several weeks, the dark compost was mixed into flower beds. This sentence provides evidence that the food scraps were transformed into something useful (compost for flowers) rather than being sent to a landfill.","incorrect":[{"choice":"A new scoreboard was installed in the gym.","category":"Irrelevant information","reason":"This sentence describes gym equipment. It does not mention food scraps or composting, so it cannot support the idea about turning food into something useful."},"",{"choice":"The passage says every reader already knew about compost bin.","category":"Unsupported claim","reason":"This statement is not found in the text. You must choose a sentence directly from the passage that proves the idea rather than adding your own opinion."},{"choice":"The title names the topic but gives no proof.","category":"Missing text evidence","reason":"Titles often introduce a topic, but they do not provide the specific actions or results needed to support a claim. You need a sentence that shows the actual process of turning scraps into soil."}]},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":9,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0010","version":3,"contentHash":"sha256:ca4a68dfe9d1e896f49f7833864ee3edf25329b84450bea248af34f6777a5883","question":"Read the passage. Grade 2 foundation passage: Science students tracked local weather patterns. They measured rainfall, wind direction, temperature, and cloud cover every day. Their chart showed that cool mornings often followed clear nights.\n\nWhich detail is the strongest evidence for the answer, \"The students gathered more than one kind of weather evidence.\"?","choices":["The passage says every reader already knew about weather station.","The music teacher tuned a violin before class.","They measured rainfall, wind direction, temperature, and cloud cover every day.","The title names the topic but gives no proof."],"correct":2,"studyAid":{"definition":"Strong evidence is a specific detail from the text that directly supports a statement or conclusion.","example":"Claim: The classroom was messy. Evidence: Papers were scattered on the floor and books were piled on the chairs.","strategyClue":"Look for a sentence that lists several different items, tools, or actions that match the specific goal mentioned in the claim.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They measured rainfall, wind direction, temperature, and cloud cover every day. This sentence lists four distinct types of data collected, proving the students gathered more than one kind of weather evidence.","incorrect":[{"choice":"The passage says every reader already knew about weather station.","category":"irrelevant information","reason":"This statement is not found in the passage and does not provide any evidence about what the students actually collected."},{"choice":"The music teacher tuned a violin before class.","category":"off-topic content","reason":"This sentence describes music class, which has nothing to do with the students tracking weather or gathering weather evidence."},"",{"choice":"The title names the topic but gives no proof.","category":"insufficient evidence","reason":"While a title might describe a topic, it does not provide the specific details or evidence needed to prove that multiple types of data were measured."}]},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":10,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0011","version":3,"contentHash":"sha256:d775e7ecd4ce8c76d3e50b8e9cfba64259c9abfa6012ea73ef7dcb0019ec9fed","question":"Read the passage. Grade 2 foundation passage: A recycling team reduced paper waste at school. They placed blue bins in classrooms and reminded students to use both sides of paper. By winter break, the school ordered fewer boxes of printer paper.\n\nWhich sentence from the passage best supports this idea: The plan changed how much paper the school used.","choices":["The title names the topic but gives no proof.","The nurse checked the first-aid supplies after lunch.","The passage says every reader already knew about recycling team.","By winter break, the school ordered fewer boxes of printer paper."],"correct":3,"studyAid":{"definition":"Supporting evidence consists of specific facts or details from the text that prove or explain a main idea or conclusion.","example":"Main Idea: The dog was tired. Supporting Evidence: He slept for three hours and refused to chase his favorite ball.","strategyClue":"Look for the specific action in the text that directly shows a difference in the 'before' and 'after' amounts mentioned in the main idea.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: By winter break, the school ordered fewer boxes of printer paper. This sentence provides direct evidence of a change in paper consumption, showing that the team's plan successfully reduced waste.","incorrect":[{"choice":"The title names the topic but gives no proof.","category":"not a sentence","reason":"This is a statement about the passage itself, not a sentence found within the text that describes the school's actions."},{"choice":"The nurse checked the first-aid supplies after lunch.","category":"irrelevant information","reason":"This sentence is not in the passage and has nothing to do with recycling or the amount of paper used by the school."},{"choice":"The passage says every reader already knew about recycling team.","category":"incorrect text evidence","reason":"The passage does not state that everyone already knew about the team; it describes the team's actions and the resulting change in paper use."},""]},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":11,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0012","version":3,"contentHash":"sha256:d1e29069df7ff80c27b983ca37ed3472e30d0f0c284879c4bac8665e7c3adf11","question":"Read the passage. Grade 2 foundation passage: Museum workers built an exhibit about local history. They displayed old tools, photographs, letters, and a map of the first town road. Visitors could press buttons to hear recordings of elders telling memories.\n\nWhich detail is the strongest evidence for the answer, \"The exhibit included both objects and personal stories.\"?","choices":["Visitors could press buttons to hear recordings of elders telling memories.","A rainstorm delayed the baseball game.","The passage says every reader already knew about museum exhibit.","The title names the topic but gives no proof."],"correct":0,"studyAid":{"definition":"Strong evidence must come directly from the text and specifically match the claim you are trying to prove.","example":"Claim: The garden has flowers. Evidence: 'The red roses and yellow tulips were in full bloom.'","strategyClue":"Highlight the keywords in the claim, such as 'objects' and 'personal stories', then look for sentences in the text that specifically name or describe those items.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Visitors could press buttons to hear recordings of elders telling memories. This sentence provides direct proof of 'personal stories' (the recordings of elders) and 'objects' (implied by the exhibit context) that support the claim.","incorrect":["",{"choice":"A rainstorm delayed the baseball game.","category":"irrelevant information","reason":"This detail is not mentioned in the passage and has nothing to do with the museum exhibit or its contents."},{"choice":"The passage says every reader already knew about museum exhibit.","category":"unsupported claim","reason":"The passage never states that readers already knew about the exhibit; this detail is not present in the text."},{"choice":"The title names the topic but gives no proof.","category":"missing evidence","reason":"A title might introduce a topic, but it does not provide the specific evidence needed to support a claim about what the exhibit actually included."}]},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":12,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0013","version":3,"contentHash":"sha256:d877b5d8f66f7d7d5e5dcf5a6ad12814d2c1ebbe13b7db70931701a4e441fa6d","question":"Read the passage. Grade 2 foundation passage: Club members improved a robot through testing. Each time the robot missed a turn, members adjusted the code and tested again. They kept notes about which wheel speed worked best on the course.\n\nWhich sentence from the passage best supports this idea: The club used mistakes as information.","choices":["The principal announced picture day over the speaker.","Each time the robot missed a turn, members adjusted the code and tested again.","The passage says every reader already knew about robotics club.","The title names the topic but gives no proof."],"correct":1,"studyAid":{"definition":"To find evidence in a text, look for sentences that show actions or reactions related to the main idea you are trying to support.","example":"Main idea: 'Dogs are helpful.' Evidence: 'My dog barked to wake me up when the alarm failed.'","strategyClue":"Look for words in the sentences that show a problem happening, and then find the sentence where the characters react to that problem by trying to fix it.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Each time the robot missed a turn, members adjusted the code and tested again. This sentence shows the students viewing a mistake (missing a turn) as a chance to learn and fix their work (adjusting the code and testing again).","incorrect":[{"choice":"The principal announced picture day over the speaker.","category":"irrelevant information","reason":"This sentence is not related to the club's robot project and does not mention mistakes or learning at all."},"",{"choice":"The passage says every reader already knew about robotics club.","category":"unsupported claim","reason":"This claim is not found in the text, and it does not explain how the club uses mistakes as information."},{"choice":"The title names the topic but gives no proof.","category":"incorrect text analysis","reason":"The title might introduce a topic, but it does not provide the specific evidence from the passage about how the club improved their robot."}]},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":13,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0014","version":3,"contentHash":"sha256:5d197380c334a575d4a9303bfc566ba2453ae8c6bf2664d9ef61247c2ecc2612","question":"Read the passage. Grade 2 foundation passage: School leaders started a breakfast cart. The cart offered fruit, yogurt, and whole-grain muffins near the front door. Students who arrived close to the bell could still choose a quick meal.\n\nWhich detail is the strongest evidence for the answer, \"The cart was designed for students with little time before class.\"?","choices":["The passage says every reader already knew about school breakfast.","The science lab received new magnifying glasses.","Students who arrived close to the bell could still choose a quick meal.","The title names the topic but gives no proof."],"correct":2,"studyAid":{"definition":"To find strong evidence, look for a sentence that directly connects the claim you are proving to a specific action or fact in the story.","example":"Claim: The library is a quiet place. Evidence: 'The librarian whispered so the students could focus on their books.' (Not: 'The library is in the middle of town.')","strategyClue":"Identify the key concept in the claim—in this case, 'little time'—and look for the option that describes a situation involving a time pressure or a fast process.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Students who arrived close to the bell could still choose a quick meal. This detail directly supports the claim that the cart was designed for students with little time because arriving 'close to the bell' implies a rush, and the 'quick meal' addresses that time constraint.","incorrect":[{"choice":"The passage says every reader already knew about school breakfast.","category":"Unsupported passage claim","reason":"This information is not present in the text and does not address the issue of students having limited time before class."},{"choice":"The science lab received new magnifying glasses.","category":"Irrelevant detail","reason":"While this might be true in some schools, it is not mentioned in this passage and has nothing to do with the breakfast cart or student schedules."},"",{"choice":"The title names the topic but gives no proof.","category":"Misunderstanding evidence usage","reason":"The question asks for the strongest evidence found in the text. Saying a title gives no proof does not provide any information about why the cart helps students with little time."}]},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":14,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0015","version":3,"contentHash":"sha256:8d934388be4e87cccb243044ef9000fc30fdfae14f0b26ead6e51e3123a773f1","question":"Read the passage. Grade 2 foundation passage: Park rangers marked a trail for visitors. They added arrows, distance signs, and small plaques naming common trees. A new bench gave hikers a place to rest near the creek.\n\nWhich sentence from the passage best supports this idea: The signs gave visitors both directions and information.","choices":["The title names the topic but gives no proof.","The post office closed early on Saturday.","The passage says every reader already knew about nature trail.","They added arrows, distance signs, and small plaques naming common trees."],"correct":3,"studyAid":{"definition":"Supporting evidence consists of specific facts or details from the text that prove your main idea is true.","example":"Main Idea: The dog was tired. Supporting Evidence: He yawned three times and curled up on his rug for a nap.","strategyClue":"Look at the main idea's keywords—'directions' and 'information'—then scan the passage for items that match those two categories.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They added arrows, distance signs, and small plaques naming common trees. This sentence provides evidence because 'arrows' and 'distance signs' offer direction, while 'plaques naming common trees' provide information.","incorrect":[{"choice":"The title names the topic but gives no proof.","category":"not in text","reason":"This sentence is not found in the passage provided. Always make sure your supporting evidence comes directly from the text itself."},{"choice":"The post office closed early on Saturday.","category":"off topic","reason":"This information is not part of the passage and does not help explain how visitors find their way or learn about the park."},{"choice":"The passage says every reader already knew about nature trail.","category":"incorrect interpretation","reason":"The passage does not state this; even if it did, knowing about a trail is not the same as having signs that provide directions and facts."},""]},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":15,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0016","version":3,"contentHash":"sha256:5dca42d05bd9c229378b7878ceca057d4b008423850c5a36c2b9e73ce13da3e1","question":"Read the passage. Grade 2 developing passage: A class kept a school garden healthy. Students watered the seedlings each morning and recorded how tall they grew. They also moved the shade cloth when the afternoon sun became too strong. These details show that students used careful daily routines to help a garden grow.\n\nWhich sentence from the passage best supports this idea: The students used observations to care for the plants.","choices":["They recorded how tall the seedlings grew.","The art room displayed clay bowls near the window.","The passage says every reader already knew about school garden.","The title names the topic but gives no proof."],"correct":0,"studyAid":{"definition":"To find evidence for a claim, look for specific details or actions in the text that directly support the idea mentioned in the question.","example":"Claim: The dog is helpful. Evidence: The dog carried the newspaper to the door every single morning.","strategyClue":"Search the passage for the specific keyword 'observations' or synonyms like 'watched', 'measured', or 'checked'. Look for the sentence that describes the action of looking at the plants closely.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They recorded how tall the seedlings grew. This sentence directly describes the students taking notes and tracking information, which is a form of observation used to monitor the plants' progress.","incorrect":["",{"choice":"The art room displayed clay bowls near the window.","category":"irrelevant information","reason":"This sentence describes an art project and bowls, which has nothing to do with the garden or the students' observations of the plants."},{"choice":"The passage says every reader already knew about school garden.","category":"not in text","reason":"The passage does not state that readers already know about the garden, and this sentence does not provide any evidence about the students' actions."},{"choice":"The title names the topic but gives no proof.","category":"analysis of title","reason":"While a title can name a topic, it does not describe the specific actions or observations the students took to care for the plants as required by the question."}]},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":16,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0017","version":3,"contentHash":"sha256:9ff2466255fc475f806f1467785aec786bbc204860c1125e228a63e8218986d8","question":"Read the passage. Grade 2 developing passage: Student volunteers made the library easier to use. They sorted returned books by call number before placing them on shelves. They made bright shelf labels for mystery, science, and biography books. These details show that student volunteers organized books and labels to make the library easier to use.\n\nWhich detail is the strongest evidence for the answer, \"The volunteers helped readers find materials more efficiently.\"?","choices":["The cafeteria served tomato soup on Thursday.","They sorted returned books by call number before placing them on shelves.","The passage says every reader already knew about library helpers.","The title names the topic but gives no proof."],"correct":1,"studyAid":{"definition":"Strong evidence is a specific fact or detail from the text that directly supports your main point or answers a question.","example":"Question: How was the dog helpful? Detail: The dog alerted the family to the fire by barking loudly.","strategyClue":"Ask yourself: 'Does this specific fact explain how the library became easier or faster to use?' If the detail is about a different topic or doesn't explain the 'how,' it is not the strongest evidence.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They sorted returned books by call number before placing them on shelves. This detail directly explains how library materials are ordered, which helps readers locate specific items faster than if books were placed randomly.","incorrect":[{"choice":"The cafeteria served tomato soup on Thursday.","category":"irrelevant information","reason":"This information is not mentioned in the passage and has nothing to do with the library or how readers find books."},"",{"choice":"The passage says every reader already knew about library helpers.","category":"unsupported claim","reason":"The passage does not state that readers already knew about the helpers, and this information would not explain why the library is more efficient."},{"choice":"The title names the topic but gives no proof.","category":"missing evidence","reason":"A title identifies what a passage is about, but it does not provide the specific facts needed to prove that the library became more efficient."}]},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":17,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0018","version":3,"contentHash":"sha256:1c16b8f1c61b4c0209fe2db3aaa90ef9aaac4f697d4026713a4fa0c5daa2b6c7","question":"Read the passage. Grade 2 developing passage: A science club collected rainwater for outdoor plants. The barrel caught water from the roof during storms. Members used the stored water on dry afternoons instead of turning on the hose. These details show that a science club collected and reused rainwater to care for plants.\n\nWhich sentence from the passage best supports this idea: The rain barrel reduced the need for hose water.","choices":["The passage says every reader already knew about rain barrel.","A soccer team practiced corner kicks after school.","Members used the stored water on dry afternoons instead of turning on the hose.","The title names the topic but gives no proof."],"correct":2,"studyAid":{"definition":"To support a claim, you must find a sentence that provides direct evidence or proof for the specific idea mentioned in the prompt.","example":"Claim: The library is a quiet place. Evidence: Students sat at their desks working silently on their reading assignments.","strategyClue":"Look for the sentence that describes a specific action taken by the subjects of the passage that directly proves the main idea.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Members used the stored water on dry afternoons instead of turning on the hose. This sentence directly shows the action of reusing stored rainwater as a replacement for using the hose.","incorrect":[{"choice":"The passage says every reader already knew about rain barrel.","category":"not in text","reason":"This information does not appear in the text provided, and it does not explain how the rain barrel helped save water."},{"choice":"A soccer team practiced corner kicks after school.","category":"irrelevant information","reason":"This sentence is about a soccer team and has nothing to do with science clubs, rain barrels, or water conservation."},"",{"choice":"The title names the topic but gives no proof.","category":"missing supporting evidence","reason":"A title might introduce a topic, but it does not provide the specific actions or details needed to support the claim that the barrel reduced hose usage."}]},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":18,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0019","version":3,"contentHash":"sha256:023ec8d14779a3000bdc667cecc4b4a4734d729c2e9e9fbec3bca6627c7b3f9a","question":"Read the passage. Grade 2 developing passage: Young reporters created a newspaper for their school. They interviewed teachers, wrote short articles, and checked facts before printing. The first issue included a sports column, a book review, and a lunch survey. These details show that student reporters gathered facts and published school news.\n\nWhich detail is the strongest evidence for the answer, \"The reporters tried to make the newspaper accurate.\"?","choices":["The title names the topic but gives no proof.","The playground slide was painted blue over spring break.","The passage says every reader already knew about class newspaper.","They interviewed teachers, wrote short articles, and checked facts before printing."],"correct":3,"studyAid":{"definition":"To find evidence for a claim, look for specific actions or descriptions in the text that directly support the idea mentioned in your question.","example":"Claim: 'The dog was tired.' Evidence: 'He curled up on his bed and closed his eyes.'","strategyClue":"Highlight the keywords in the question, then scan the text specifically looking for sentences that show people doing something to confirm or verify information.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They interviewed teachers, wrote short articles, and checked facts before printing. Checking facts is the direct action of verifying information to ensure it is true, which is the definition of accuracy.","incorrect":[{"choice":"The title names the topic but gives no proof.","category":"irrelevant information","reason":"The title is not mentioned in the passage, and even if it were, a title only labels a topic rather than providing evidence of the work put into accuracy."},{"choice":"The playground slide was painted blue over spring break.","category":"unrelated detail","reason":"This information is not found in the passage and does not relate to the reporters' work or the accuracy of the newspaper."},{"choice":"The passage says every reader already knew about class newspaper.","category":"factual inaccuracy","reason":"The passage never mentions what the readers knew; always check back to the text to ensure the evidence provided actually exists."},""]},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":19,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0020","version":3,"contentHash":"sha256:dd8a8fb4423f7dbaade21dff3d33c08ede0f88de62add2e05cf13d2fb1d33378","question":"Read the passage. Grade 2 developing passage: Families removed litter from the beach. They filled ten bags with plastic wrappers, bottle caps, and broken fishing line. Afterward, volunteers posted signs reminding visitors to pack out trash. These details show that families cleaned litter from the beach and encouraged visitors to keep it clean.\n\nWhich sentence from the passage best supports this idea: The cleanup made the beach safer for wildlife.","choices":["They filled ten bags with plastic wrappers, bottle caps, and broken fishing line.","The town band played a concert in the park.","The passage says every reader already knew about beach cleanup.","The title names the topic but gives no proof."],"correct":0,"studyAid":{"definition":"Supporting details are the specific facts, examples, or evidence provided in a text that help prove or explain the main idea.","example":"Main idea: 'It was a cold day.' Supporting detail: 'Ice covered the sidewalk.' OR Main idea: 'The dog was tired.' Supporting detail: 'He slept for six hours.'","strategyClue":"Look for the specific detail that describes the 'how' or 'what' behind the claim of safety; ignore general statements or information about things unrelated to the beach.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They filled ten bags with plastic wrappers, bottle caps, and broken fishing line. This sentence provides specific evidence of the volume of dangerous items removed from the beach, which directly supports the claim that the beach became safer for wildlife.","incorrect":["",{"choice":"The town band played a concert in the park.","category":"irrelevant information","reason":"This sentence mentions a band and a park, which is unrelated to the topic of beach cleanup or wildlife safety."},{"choice":"The passage says every reader already knew about beach cleanup.","category":"unsupported claim","reason":"This is an assumption about the reader's knowledge, not a detail from the text that proves the cleanup improved conditions for animals."},{"choice":"The title names the topic but gives no proof.","category":"structural analysis","reason":"While titles identify a topic, they do not provide the concrete evidence or specific details needed to prove how a specific goal, like wildlife safety, was achieved."}]},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":20,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0021","version":3,"contentHash":"sha256:bfb15799eea3e6cd8d345408a771b271591642a40c25c5b5a1931e7b76443397","question":"Read the passage. Grade 2 developing passage: A safety officer taught students how to ride bikes safely. She showed how helmets should sit flat and snug on a rider's head. She reminded riders to signal turns and watch for opening car doors. These details show that a safety officer taught students important bike safety habits.\n\nWhich detail is the strongest evidence for the answer, \"A helmet must fit correctly to protect a rider.\"?","choices":["The school choir rehearsed a song about the moon.","She showed how helmets should sit flat and snug on a rider's head.","The passage says every reader already knew about bike safety.","The title names the topic but gives no proof."],"correct":1,"studyAid":{"definition":"Evidence is a specific detail or fact from the text that proves your answer is correct. Strong evidence must directly relate to the main idea you are supporting.","example":"Main idea: Dogs are helpful pets. Evidence: 'My dog helps me find my lost keys every morning.'","strategyClue":"Look for the sentence in the text that specifically describes the action or rule mentioned in your target statement. Ignore sentences about different topics or general summaries that lack specific details.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: She showed how helmets should sit flat and snug on a rider's head. This sentence provides specific instructions on the proper positioning and fit of a helmet, which directly supports the requirement for a helmet to be worn correctly to provide protection.","incorrect":[{"choice":"The school choir rehearsed a song about the moon.","category":"irrelevant information","reason":"This information is not present in the passage and does not relate to bike safety or the importance of a properly fitted helmet."},"",{"choice":"The passage says every reader already knew about bike safety.","category":"inaccurate claim","reason":"The passage does not state that readers already knew about bike safety; it describes the officer teaching students these habits."},{"choice":"The title names the topic but gives no proof.","category":"missing supporting evidence","reason":"While a title might name a topic, it does not provide the specific instructional details needed to prove how a helmet should fit."}]},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":21,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0022","version":3,"contentHash":"sha256:8b4287b644e38137627788fb0bcd35b15cd71aa05a45f876c429938f72d4e58b","question":"Read the passage. Grade 2 developing passage: Transportation planners added bus routes near busy neighborhoods. The new route stopped near the clinic, grocery store, and community center. Riders waited less time because buses arrived every fifteen minutes. These details show that transportation planners improved bus service so people could reach useful places.\n\nWhich sentence from the passage best supports this idea: The new bus route served community needs.","choices":["The passage says every reader already knew about city buses.","A bakery sold cinnamon rolls before sunrise.","The new route stopped near the clinic, grocery store, and community center.","The title names the topic but gives no proof."],"correct":2,"studyAid":{"definition":"To support an idea, find a sentence in the text that gives a specific fact or example that matches the main point.","example":"Idea: Dogs are helpful. Evidence: My dog barks when someone knocks at the door.","strategyClue":"Look at the key words in the idea ('community needs'). Scan the passage for sentences that list specific places people go to, then check if those places count as community resources.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: The new route stopped near the clinic, grocery store, and community center. This sentence provides specific examples of destinations that people in the community need to visit, directly supporting the idea that the new route serves community needs.","incorrect":[{"choice":"The passage says every reader already knew about city buses.","category":"not in text","reason":"This information is not found in the passage. Always look for evidence directly stated in the text to support your conclusion."},{"choice":"A bakery sold cinnamon rolls before sunrise.","category":"irrelevant information","reason":"While this sentence mentions a location, it does not connect to the topic of bus routes or transportation planning. It does not provide evidence about community needs."},"",{"choice":"The title names the topic but gives no proof.","category":"misunderstanding the prompt","reason":"This is a statement about a title, not a piece of evidence from the text. You must select a sentence from the passage that proves the service improved."}]},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":22,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0023","version":3,"contentHash":"sha256:4f8182ef3078a821ea7ad575b1f38327903510851d191ffd6cdb181eb38fe7d9","question":"Read the passage. Grade 2 developing passage: Cast members prepared a play through teamwork. Actors practiced lines while stage crew members painted scenery and tested lights. When a curtain rope tangled, two students fixed it before rehearsal began. These details show that actors and crew members cooperated to get a play ready.\n\nWhich detail is the strongest evidence for the answer, \"The production required more than acting.\"?","choices":["The title names the topic but gives no proof.","A math poster showed different kinds of triangles.","The passage says every reader already knew about school play.","Actors practiced lines while stage crew members painted scenery and tested lights."],"correct":3,"studyAid":{"definition":"Strong evidence is a specific fact or detail from the text that directly supports a claim or answers a question.","example":"Claim: Dogs are helpful. Evidence: My dog barks when someone is at the door to warn me.","strategyClue":"Look for the sentence that describes people doing different types of work mentioned in the claim. Eliminate any options that are not found in the passage or that discuss a completely different topic.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Actors practiced lines while stage crew members painted scenery and tested lights. This sentence explicitly mentions both actors and crew members performing different tasks, proving that the production involved work beyond just acting.","incorrect":[{"choice":"The title names the topic but gives no proof.","category":"irrelevant information","reason":"This is a commentary on structure rather than evidence from the text; it does not describe an action that requires non-acting labor."},{"choice":"A math poster showed different kinds of triangles.","category":"off-topic detail","reason":"This information is unrelated to the process of putting on a play and does not support the idea that the production required more than acting."},{"choice":"The passage says every reader already knew about school play.","category":"unsupported claim","reason":"This statement is not found in the text and does not provide any evidence about the specific roles needed for a theatrical production."},""]},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":23,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0024","version":3,"contentHash":"sha256:c154caa82e42b845ac0d6e15161b35a9360ea14b0baa39dbd01ee3c35e14dc4b","question":"Read the passage. Grade 2 developing passage: Cafeteria workers turned food scraps into compost. Fruit peels and vegetable ends went into a covered bin behind the cafeteria. After several weeks, the dark compost was mixed into flower beds. These details show that cafeteria food scraps were collected and turned into compost for flowers.\n\nWhich sentence from the passage best supports this idea: Food scraps can become useful instead of being thrown away.","choices":["After several weeks, the dark compost was mixed into flower beds.","A new scoreboard was installed in the gym.","The passage says every reader already knew about compost bin.","The title names the topic but gives no proof."],"correct":0,"studyAid":{"definition":"To support an idea, look for evidence that shows a specific action or result related to that idea.","example":"If the idea is 'The dog is messy,' the supporting sentence is 'The dog tracked mud all over the rug.'","strategyClue":"Look at the key words in the idea ('food scraps', 'useful', 'not thrown away') and find the sentence that describes a specific action happening to the food scraps.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: After several weeks, the dark compost was mixed into flower beds. This sentence shows the scraps were transformed into something useful (compost) rather than simply being discarded, directly supporting the idea that food scraps can be useful.","incorrect":["",{"choice":"A new scoreboard was installed in the gym.","category":"off-topic information","reason":"This sentence describes a different event in the school that has nothing to do with food scraps or composting."},{"choice":"The passage says every reader already knew about compost bin.","category":"not in text","reason":"This is a statement about the reader's knowledge, not a sentence from the passage that provides evidence about what happens to food scraps."},{"choice":"The title names the topic but gives no proof.","category":"lacks supporting evidence","reason":"A title might introduce a subject, but it does not contain the specific details or actions needed to prove the claim about food scraps becoming useful."}]},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":24,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0025","version":3,"contentHash":"sha256:75ba56e1517a57cdc508d633cf9c6d1552c68a7c541734b2a1e08b5e905ec55d","question":"Read the passage. Grade 2 developing passage: Science students tracked local weather patterns. They measured rainfall, wind direction, temperature, and cloud cover every day. Their chart showed that cool mornings often followed clear nights. These details show that science students recorded weather measurements and used them to find patterns.\n\nWhich detail is the strongest evidence for the answer, \"The students gathered more than one kind of weather evidence.\"?","choices":["The music teacher tuned a violin before class.","They measured rainfall, wind direction, temperature, and cloud cover every day.","The passage says every reader already knew about weather station.","The title names the topic but gives no proof."],"correct":1,"studyAid":{"definition":"To find evidence for a claim, look for the specific sentence in the text that mentions the exact details related to that claim.","example":"Claim: The classroom was messy. Evidence: Papers were scattered on the floor and paint was spilled on every desk.","strategyClue":"Highlight the key words in the question, such as 'weather evidence' and 'more than one', then scan the text for a list of items that match those keywords.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They measured rainfall, wind direction, temperature, and cloud cover every day. This sentence lists four distinct types of data the students collected, which provides direct proof that they gathered more than one kind of weather evidence.","incorrect":[{"choice":"The music teacher tuned a violin before class.","category":"irrelevant information","reason":"This sentence is not in the passage and mentions a music teacher instead of science students, so it provides no evidence for the claim."},"",{"choice":"The passage says every reader already knew about weather station.","category":"inaccurate summary","reason":"This information is not found in the text, and it does not explain how the students collected different types of weather data."},{"choice":"The title names the topic but gives no proof.","category":"missing supporting evidence","reason":"A title might describe what a passage is about, but it does not contain the specific facts or data points needed to prove the students gathered multiple kinds of weather measurements."}]},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":25,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0026","version":3,"contentHash":"sha256:c58a6bb83823dfaee073c3f23526b09b2e2fbdfc6bad2e134c8936f8b6d40179","question":"Read the passage. Grade 2 developing passage: A recycling team reduced paper waste at school. They placed blue bins in classrooms and reminded students to use both sides of paper. By winter break, the school ordered fewer boxes of printer paper. These details show that a recycling team used bins and reminders to reduce paper waste.\n\nWhich sentence from the passage best supports this idea: The plan changed how much paper the school used.","choices":["The passage says every reader already knew about recycling team.","The nurse checked the first-aid supplies after lunch.","By winter break, the school ordered fewer boxes of printer paper.","The title names the topic but gives no proof."],"correct":2,"studyAid":{"definition":"Supporting evidence is a fact or detail from the text that directly proves a claim or idea is true.","example":"Claim: The weather was bad. Evidence: The school baseball game was cancelled due to heavy rain.","strategyClue":"Look for the sentence that connects the 'action' (the plan) to the 'result' (a measurable change in quantity or behavior).","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: By winter break, the school ordered fewer boxes of printer paper. This sentence provides direct evidence of the 'result' of the plan, showing the actual reduction in paper usage.","incorrect":[{"choice":"The passage says every reader already knew about recycling team.","category":"Unsupported claim","reason":"This information is not present in the text and does not explain the success of the recycling plan."},{"choice":"The nurse checked the first-aid supplies after lunch.","category":"Irrelevant information","reason":"The nurse's activities do not relate to the paper recycling team or the reduction of paper waste."},"",{"choice":"The title names the topic but gives no proof.","category":"Missing evidence","reason":"While titles describe topics, they do not provide the factual proof needed to support how a plan changed usage patterns."}]},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":26,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0027","version":3,"contentHash":"sha256:c401f7fdc9a1bc34cbc43e85e3ba592d12449bd25c726969ddbd142e72af1c50","question":"Read the passage. Grade 2 developing passage: Museum workers built an exhibit about local history. They displayed old tools, photographs, letters, and a map of the first town road. Visitors could press buttons to hear recordings of elders telling memories. These details show that museum workers created an exhibit that helped visitors learn local history.\n\nWhich detail is the strongest evidence for the answer, \"The exhibit included both objects and personal stories.\"?","choices":["The title names the topic but gives no proof.","A rainstorm delayed the baseball game.","The passage says every reader already knew about museum exhibit.","Visitors could press buttons to hear recordings of elders telling memories."],"correct":3,"studyAid":{"definition":"Strong evidence must directly support the claim being made by mentioning specific details from the text that match the key parts of the claim.","example":"Claim: The park has activities for kids. Evidence: There is a playground with swings and a sandpit.","strategyClue":"Highlight the two main parts of the claim—in this case, 'objects' and 'personal stories'—then scan the passage for sentences that mention both types of information.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Visitors could press buttons to hear recordings of elders telling memories. This sentence provides evidence for 'personal stories' (the recordings of elders) and implies an 'object' or feature (the buttons/exhibit) that visitors interact with.","incorrect":[{"choice":"The title names the topic but gives no proof.","category":"missing supporting evidence","reason":"The passage does not provide a title. Even if it did, a title usually describes the subject but rarely contains the specific evidence needed to support a claim about content."},{"choice":"A rainstorm delayed the baseball game.","category":"irrelevant information","reason":"This information is not mentioned in the passage and has nothing to do with museum exhibits or historical records."},{"choice":"The passage says every reader already knew about museum exhibit.","category":"unsupported claim","reason":"The passage never mentions what the readers already know. Always look for information that is explicitly stated in the text provided."},""]},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":27,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0028","version":3,"contentHash":"sha256:19e9b3cfb47a31d237a87eaef7be81b318dfae8c3a83081100be31ad7c5f2cad","question":"Read the passage. Grade 2 developing passage: Club members improved a robot through testing. Each time the robot missed a turn, members adjusted the code and tested again. They kept notes about which wheel speed worked best on the course. These details show that club members tested a robot, changed its code, and used notes to improve it.\n\nWhich sentence from the passage best supports this idea: The club used mistakes as information.","choices":["Each time the robot missed a turn, members adjusted the code and tested again.","The principal announced picture day over the speaker.","The passage says every reader already knew about robotics club.","The title names the topic but gives no proof."],"correct":0,"studyAid":{"definition":"To find evidence in a passage, look for a sentence that provides a specific example or action that matches the main idea you are trying to prove.","example":"Main idea: 'Dogs are helpful.' Evidence: 'The dog barked to warn the family about the smoke.' (Not: 'The dog likes to run.')","strategyClue":"Look at the main idea phrase, then scan each option to see which one describes a character actually doing something that solves a problem or proves the statement true.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Each time the robot missed a turn, members adjusted the code and tested again. This sentence shows the club identifying a mistake (the robot missing a turn) and using that information to take action (adjusting the code and testing again).","incorrect":["",{"choice":"The principal announced picture day over the speaker.","category":"unrelated topic","reason":"This sentence is about a principal and picture day; it has nothing to do with the robotics club or learning from mistakes."},{"choice":"The passage says every reader already knew about robotics club.","category":"not in text","reason":"This statement is not found in the passage provided, and it does not explain how the club uses mistakes to improve their project."},{"choice":"The title names the topic but gives no proof.","category":"misunderstanding evidence","reason":"This statement talks about a title, which doesn't provide evidence or actions from the club members to support the idea of learning from errors."}]},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":28,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0029","version":3,"contentHash":"sha256:d9c565bbd36b8c490cb7a1551ba211dad67ed3ac86d456b61e7d63da01703a49","question":"Read the passage. Grade 2 developing passage: School leaders started a breakfast cart. The cart offered fruit, yogurt, and whole-grain muffins near the front door. Students who arrived close to the bell could still choose a quick meal. These details show that school leaders made breakfast easier for busy students to get.\n\nWhich detail is the strongest evidence for the answer, \"The cart was designed for students with little time before class.\"?","choices":["The science lab received new magnifying glasses.","Students who arrived close to the bell could still choose a quick meal.","The passage says every reader already knew about school breakfast.","The title names the topic but gives no proof."],"correct":1,"studyAid":{"definition":"Strong evidence is a specific fact or detail from the text that directly supports the point you are trying to prove.","example":"Claim: The dog was hungry. Evidence: He ate his food in ten seconds and licked the empty bowl.","strategyClue":"Find the key words in the question, such as 'little time'. Look for the sentence in the text that mentions a similar concept, like 'close to the bell'.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Students who arrived close to the bell could still choose a quick meal. This detail specifically connects 'arriving close to the bell' (having little time) with the ability to 'choose a quick meal' (a solution for lack of time).","incorrect":[{"choice":"The science lab received new magnifying glasses.","category":"irrelevant information","reason":"This detail is about science equipment and has no connection to the school breakfast cart or how much time students have before class."},"",{"choice":"The passage says every reader already knew about school breakfast.","category":"unsupported claim","reason":"The passage does not state that readers already knew this information, and knowing about a program is not the same as evidence that a cart saves time."},{"choice":"The title names the topic but gives no proof.","category":"missing text evidence","reason":"A title is just a label for a topic. To support a specific claim, you need a detail from the body of the text that explains a behavior or reason."}]},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":29,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0030","version":3,"contentHash":"sha256:ba13d99a606736351ca2155b88096c4bfe15b2aa0cda4c6c03617df8a3f38f48","question":"Read the passage. Grade 2 developing passage: Park rangers marked a trail for visitors. They added arrows, distance signs, and small plaques naming common trees. A new bench gave hikers a place to rest near the creek. These details show that park rangers marked a trail so visitors could navigate and learn.\n\nWhich sentence from the passage best supports this idea: The signs gave visitors both directions and information.","choices":["The passage says every reader already knew about nature trail.","The post office closed early on Saturday.","They added arrows, distance signs, and small plaques naming common trees.","The title names the topic but gives no proof."],"correct":2,"studyAid":{"definition":"Supporting evidence consists of specific facts or details from the text that prove why the main idea is true.","example":"Main idea: 'My dog is helpful.' Evidence: 'He carries the morning newspaper to the front door.'","strategyClue":"Look for a sentence that lists concrete items or actions described in the passage that match the keywords 'directions' and 'information'.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They added arrows, distance signs, and small plaques naming common trees. This sentence directly provides evidence for both directions (arrows and signs) and information (plaques naming trees).","incorrect":[{"choice":"The passage says every reader already knew about nature trail.","category":"unsupported text claim","reason":"This information is not present in the passage provided. Always make sure your supporting evidence comes directly from the text itself."},{"choice":"The post office closed early on Saturday.","category":"irrelevant information","reason":"This sentence is completely unrelated to the topic of park rangers or hiking trails. It does not provide any support for the main idea."},"",{"choice":"The title names the topic but gives no proof.","category":"misunderstanding evidence","reason":"While titles identify a topic, they do not provide the specific details needed to support a claim about how rangers assist visitors."}]},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":30,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0031","version":3,"contentHash":"sha256:791aa312a2c50c04f1a61a4b7d60b05a6134449699e15ce621d1780b4d66f8ec","question":"Read the passage. Grade 2 challenge passage: A class kept a school garden healthy. Students watered the seedlings each morning and recorded how tall they grew. They also moved the shade cloth when the afternoon sun became too strong. Because the passage connects actions with results, readers can see why daily care helped the school garden grow well.\n\nWhich sentence from the passage best supports this idea: The students used observations to care for the plants.","choices":["The title names the topic but gives no proof.","The art room displayed clay bowls near the window.","The passage says every reader already knew about school garden.","They recorded how tall the seedlings grew."],"correct":3,"studyAid":{"definition":"Supporting evidence is a sentence from the text that gives concrete facts or examples to prove a main idea or claim.","example":"Claim: The dog is hungry. Evidence: The dog sat by his empty bowl and whined.","strategyClue":"Look for the specific action word or behavior mentioned in the question (in this case, 'observations') and scan the text for a sentence that describes a person performing that specific action.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They recorded how tall the seedlings grew. This sentence directly describes the students taking measurements, which is an example of using observation to track the progress and health of the plants.","incorrect":[{"choice":"The title names the topic but gives no proof.","category":"irrelevant information","reason":"This statement describes a general feature of titles rather than providing specific evidence from the passage about the students' actions."},{"choice":"The art room displayed clay bowls near the window.","category":"off-topic detail","reason":"This sentence mentions objects and a location not found in the passage, so it cannot support the idea of students caring for plants."},{"choice":"The passage says every reader already knew about school garden.","category":"unsupported claim","reason":"The passage does not state what readers already know; it describes the specific actions students took to maintain the garden."},""]},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":31,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0032","version":3,"contentHash":"sha256:737a542704314ecf8533a8745ee339d98839a78092905aacef78b13a1d00c945","question":"Read the passage. Grade 2 challenge passage: Student volunteers made the library easier to use. They sorted returned books by call number before placing them on shelves. They made bright shelf labels for mystery, science, and biography books. Because the passage connects actions with results, readers can see why student helpers organized the library so readers could find books faster.\n\nWhich detail is the strongest evidence for the answer, \"The volunteers helped readers find materials more efficiently.\"?","choices":["They sorted returned books by call number before placing them on shelves.","The cafeteria served tomato soup on Thursday.","The passage says every reader already knew about library helpers.","The title names the topic but gives no proof."],"correct":0,"studyAid":{"definition":"Strong evidence is a specific fact or detail from the text that directly supports a claim or answers a question about what happened.","example":"Claim: The classroom was messy. Evidence: Papers were scattered across the floor.","strategyClue":"Ask yourself which choice describes an action that actually changes how the library functions, rather than just stating a general fact or unrelated information.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They sorted returned books by call number before placing them on shelves. This detail directly explains how organizing books by a specific system makes them easier to locate compared to a disorganized collection.","incorrect":["",{"choice":"The cafeteria served tomato soup on Thursday.","category":"irrelevant information","reason":"This information is not about the library or the volunteers, so it cannot provide evidence for how the library became more efficient."},{"choice":"The passage says every reader already knew about library helpers.","category":"unsupported claim","reason":"The passage does not state that every reader knew about the helpers, and even if they did, this would not explain *how* the materials were found more efficiently."},{"choice":"The title names the topic but gives no proof.","category":"missing evidence","reason":"The title might tell us what the story is about, but it does not contain the specific actions performed by volunteers that led to faster book retrieval."}]},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":32,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0033","version":3,"contentHash":"sha256:af8ec9dc00e8c2f8560981cf99606d8c1105cd25ac2ad81b02b4e8297cf16de5","question":"Read the passage. Grade 2 challenge passage: A science club collected rainwater for outdoor plants. The barrel caught water from the roof during storms. Members used the stored water on dry afternoons instead of turning on the hose. Because the passage connects actions with results, readers can see why a rain barrel helped the club save water for plants.\n\nWhich sentence from the passage best supports this idea: The rain barrel reduced the need for hose water.","choices":["A soccer team practiced corner kicks after school.","Members used the stored water on dry afternoons instead of turning on the hose.","The passage says every reader already knew about rain barrel.","The title names the topic but gives no proof."],"correct":1,"studyAid":{"definition":"Supporting evidence is information from the text that directly proves or explains why a statement or main idea is true.","example":"Main idea: The dog was hungry. Evidence: He ate his food in two bites.","strategyClue":"Identify the key words in the goal statement (like 'reduced' or 'hose water'), then look for the sentence that describes the specific action taken to achieve that goal.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Members used the stored water on dry afternoons instead of turning on the hose. This sentence directly describes the action of using saved rainwater as a replacement for using the garden hose.","incorrect":[{"choice":"A soccer team practiced corner kicks after school.","category":"irrelevant information","reason":"This sentence is about soccer, not a science club or rainwater, so it provides no support for the idea of saving water."},"",{"choice":"The passage says every reader already knew about rain barrel.","category":"inaccurate claim","reason":"The passage does not state that readers already knew about rain barrels, and this idea does not explain how water was saved."},{"choice":"The title names the topic but gives no proof.","category":"missing evidence","reason":"While a title might name a topic, it does not describe specific actions taken by the club to reduce the need for hose water."}]},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":33,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0034","version":3,"contentHash":"sha256:6fb2a5f98449313604b1a72580fd97f1bda4d9fd36d9364c2d798ba1fcbdb801","question":"Read the passage. Grade 2 challenge passage: Young reporters created a newspaper for their school. They interviewed teachers, wrote short articles, and checked facts before printing. The first issue included a sports column, a book review, and a lunch survey. Because the passage connects actions with results, readers can see why the class newspaper gave students a careful way to share school news.\n\nWhich detail is the strongest evidence for the answer, \"The reporters tried to make the newspaper accurate.\"?","choices":["The passage says every reader already knew about class newspaper.","The playground slide was painted blue over spring break.","They interviewed teachers, wrote short articles, and checked facts before printing.","The title names the topic but gives no proof."],"correct":2,"studyAid":{"definition":"To find evidence, look for specific actions or descriptions in the text that directly support the claim or main idea you are investigating.","example":"Claim: 'The character was tired.' Evidence: 'He yawned repeatedly and rubbed his heavy eyes.'","strategyClue":"Highlight the claim in the question, then go back to the text to find the exact sentence where the author describes the characters doing work or taking specific actions related to that claim.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They interviewed teachers, wrote short articles, and checked facts before printing. This sentence directly describes the steps the reporters took to ensure their information was correct, providing evidence for their accuracy.","incorrect":[{"choice":"The passage says every reader already knew about class newspaper.","category":"Unsupported by text","reason":"This detail is not mentioned in the passage, and even if it were, it does not explain how the reporters ensured their work was accurate."},{"choice":"The playground slide was painted blue over spring break.","category":"Irrelevant information","reason":"This detail is completely unrelated to the reporters, their writing process, or the newspaper, so it cannot serve as evidence for accuracy."},"",{"choice":"The title names the topic but gives no proof.","category":"Missing evidence","reason":"This choice refers to a feature of a newspaper but does not offer any specific evidence about the reporters' work or their commitment to being accurate."}]},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":34,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0035","version":3,"contentHash":"sha256:f3e4aa15cfa5845e8897c773c0fa312fd755c1714a5e9a8bb8e447220b80e898","question":"Read the passage. Grade 2 challenge passage: Families removed litter from the beach. They filled ten bags with plastic wrappers, bottle caps, and broken fishing line. Afterward, volunteers posted signs reminding visitors to pack out trash. Because the passage connects actions with results, readers can see why the cleanup protected the beach by removing harmful litter.\n\nWhich sentence from the passage best supports this idea: The cleanup made the beach safer for wildlife.","choices":["The title names the topic but gives no proof.","The town band played a concert in the park.","The passage says every reader already knew about beach cleanup.","They filled ten bags with plastic wrappers, bottle caps, and broken fishing line."],"correct":3,"studyAid":{"definition":"Supporting evidence is a specific fact or detail from a text that proves or explains the main idea.","example":"Main idea: Dogs are helpful pets. Supporting detail: My dog helps me feel safe at night.","strategyClue":"Look for a sentence that lists concrete items or actions that were removed from the beach, as these explain exactly how the environment was made safer.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They filled ten bags with plastic wrappers, bottle caps, and broken fishing line. This sentence provides evidence of the cleanup actions that directly remove harmful items, explaining how the environment became safer for animals.","incorrect":[{"choice":"The title names the topic but gives no proof.","category":"not in text","reason":"The passage does not contain a title. Furthermore, this option does not describe an action from the text that would make a beach safer for wildlife."},{"choice":"The town band played a concert in the park.","category":"irrelevant information","reason":"This information is not found in the passage and has no connection to beach cleanup or protecting wildlife."},{"choice":"The passage says every reader already knew about beach cleanup.","category":"misinterpretation of text","reason":"The passage describes specific actions taken by volunteers, not what the reader may or may not already know."},""]},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":35,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0036","version":3,"contentHash":"sha256:3a5efef07c0530d3628ed631254be0e59573708488fd7e095dbb498f60760f14","question":"Read the passage. Grade 2 challenge passage: A safety officer taught students how to ride bikes safely. She showed how helmets should sit flat and snug on a rider's head. She reminded riders to signal turns and watch for opening car doors. Because the passage connects actions with results, readers can see why bike riders can prevent injuries by following safety rules.\n\nWhich detail is the strongest evidence for the answer, \"A helmet must fit correctly to protect a rider.\"?","choices":["She showed how helmets should sit flat and snug on a rider's head.","The school choir rehearsed a song about the moon.","The passage says every reader already knew about bike safety.","The title names the topic but gives no proof."],"correct":0,"studyAid":{"definition":"Strong evidence must directly support the main point by providing specific details, facts, or descriptions from the text.","example":"Point: Dogs need exercise. Evidence: Dogs that walk daily are healthier and happier.","strategyClue":"Highlight the key words in the target statement—in this case, 'helmet' and 'fit correctly'—then look for the sentence in the text that provides the specific instruction or description related to those two topics.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: She showed how helmets should sit flat and snug on a rider's head. This sentence provides direct evidence regarding the requirement of a proper helmet fit, specifically describing how the helmet must be positioned to be effective.","incorrect":["",{"choice":"The school choir rehearsed a song about the moon.","category":"irrelevant information","reason":"This detail is not mentioned in the passage and has no connection to bike safety or how a helmet should fit."},{"choice":"The passage says every reader already knew about bike safety.","category":"unsupported claim","reason":"The passage never makes this claim; it focuses on teaching safety rules rather than the prior knowledge of the readers."},{"choice":"The title names the topic but gives no proof.","category":"missing evidence","reason":"A title might introduce a topic, but it does not provide the specific, descriptive details needed to prove how a helmet must fit."}]},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":36,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0037","version":3,"contentHash":"sha256:2f392b1990debdb2c99615592838579165f93a0e3a4373358cfcdb7f3fc3e24f","question":"Read the passage. Grade 2 challenge passage: Transportation planners added bus routes near busy neighborhoods. The new route stopped near the clinic, grocery store, and community center. Riders waited less time because buses arrived every fifteen minutes. Because the passage connects actions with results, readers can see why new bus routes made important places easier to reach.\n\nWhich sentence from the passage best supports this idea: The new bus route served community needs.","choices":["A bakery sold cinnamon rolls before sunrise.","The new route stopped near the clinic, grocery store, and community center.","The passage says every reader already knew about city buses.","The title names the topic but gives no proof."],"correct":1,"studyAid":{"definition":"Supporting evidence consists of facts, details, or examples from a text that directly prove or explain the main idea.","example":"Main Idea: The park is fun. Evidence: There is a new slide, a baseball field, and a colorful playground.","strategyClue":"Look for a sentence that lists specific places or actions related to 'community needs' and compare it to the main idea to see if it acts as proof.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: The new route stopped near the clinic, grocery store, and community center. This sentence provides direct evidence of how the bus route connects residents to important local services, which supports the claim that the route serves community needs.","incorrect":[{"choice":"A bakery sold cinnamon rolls before sunrise.","category":"irrelevant information","reason":"While this sentence describes a business, it does not mention the bus route or how the transportation system helps people reach community locations."},"",{"choice":"The passage says every reader already knew about city buses.","category":"unsupported claim","reason":"The passage never claims that readers already know about the buses; it provides facts about the new routes to inform the reader."},{"choice":"The title names the topic but gives no proof.","category":"off-topic assertion","reason":"This comment describes a title, which does not act as evidence to support the idea that the bus route helps the community."}]},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":37,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0038","version":3,"contentHash":"sha256:bd1793cd373e4597616f70e1cd60c5a7df4a38a7fbe4d373accd3fa5ecc41431","question":"Read the passage. Grade 2 challenge passage: Cast members prepared a play through teamwork. Actors practiced lines while stage crew members painted scenery and tested lights. When a curtain rope tangled, two students fixed it before rehearsal began. Because the passage connects actions with results, readers can see why many students worked together to prepare the school play.\n\nWhich detail is the strongest evidence for the answer, \"The production required more than acting.\"?","choices":["The passage says every reader already knew about school play.","A math poster showed different kinds of triangles.","Actors practiced lines while stage crew members painted scenery and tested lights.","The title names the topic but gives no proof."],"correct":2,"studyAid":{"definition":"Strong evidence is a specific fact or detail from the text that directly supports your answer to a question.","example":"Question: How do we know the dog was happy? Evidence: The dog wagged its tail and jumped up when I came home.","strategyClue":"Look for a sentence that lists specific tasks performed by people who are not actors. If the sentence shows work being done that isn't about speaking lines, that is the proof you need.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Actors practiced lines while stage crew members painted scenery and tested lights. This sentence provides evidence of different roles, such as stage crew members handling lights and scenery, proving that the play needed more than just actors to be successful.","incorrect":[{"choice":"The passage says every reader already knew about school play.","category":"unsupported claim","reason":"This information does not appear in the text and does not address the different roles required to build a stage production."},{"choice":"A math poster showed different kinds of triangles.","category":"irrelevant information","reason":"This detail is completely unrelated to the school play or the efforts required to put on a performance."},"",{"choice":"The title names the topic but gives no proof.","category":"lack of evidence","reason":"A title might introduce a subject, but it cannot act as evidence to prove that a production requires more than just acting."}]},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":38,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0039","version":3,"contentHash":"sha256:6973c06019a80f3c93de5c1372f7e60d2fc3b5fb40be8f514d6f56254280305f","question":"Read the passage. Grade 2 challenge passage: Cafeteria workers turned food scraps into compost. Fruit peels and vegetable ends went into a covered bin behind the cafeteria. After several weeks, the dark compost was mixed into flower beds. Because the passage connects actions with results, readers can see why composting changed cafeteria scraps into useful soil material.\n\nWhich sentence from the passage best supports this idea: Food scraps can become useful instead of being thrown away.","choices":["The title names the topic but gives no proof.","A new scoreboard was installed in the gym.","The passage says every reader already knew about compost bin.","After several weeks, the dark compost was mixed into flower beds."],"correct":3,"studyAid":{"definition":"Supporting evidence is a detail, sentence, or fact from a text that proves a main idea or claim is true.","example":"Claim: The classroom is messy. Evidence: There are papers on the floor and crayons under the desk.","strategyClue":"Look for a sentence that describes a direct action resulting in the transformation of the scraps into something else. Ask yourself: 'Which sentence proves the scraps did not just sit in the bin forever?'","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: After several weeks, the dark compost was mixed into flower beds. This sentence provides the specific evidence that the food scraps mentioned in the passage were used to nourish soil, which directly supports the idea that scraps can become useful.","incorrect":[{"choice":"The title names the topic but gives no proof.","category":"not in text","reason":"This is an observation about a title, not a sentence from the text. It does not contain evidence or show the transformation of the food scraps."},{"choice":"A new scoreboard was installed in the gym.","category":"irrelevant information","reason":"This information is not found in the passage provided. Even if it were true, it does not relate to food scraps or composting."},{"choice":"The passage says every reader already knew about compost bin.","category":"unsupported claim","reason":"The passage does not state this, and it does not show how food scraps become useful. This choice does not provide supporting evidence for the central idea."},""]},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":39,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0040","version":3,"contentHash":"sha256:385304a7d8603b86c18d9aa70b7794baa98b989bf01f62de1febd5fba25a8bbe","question":"Read the passage. Grade 2 challenge passage: Science students tracked local weather patterns. They measured rainfall, wind direction, temperature, and cloud cover every day. Their chart showed that cool mornings often followed clear nights. Because the passage connects actions with results, readers can see why students collected weather data to notice local patterns.\n\nWhich detail is the strongest evidence for the answer, \"The students gathered more than one kind of weather evidence.\"?","choices":["They measured rainfall, wind direction, temperature, and cloud cover every day.","The music teacher tuned a violin before class.","The passage says every reader already knew about weather station.","The title names the topic but gives no proof."],"correct":0,"studyAid":{"definition":"Strong evidence is a specific fact or detail from the text that directly proves the answer to a question.","example":"Question: Was the puppy hungry? Evidence: The puppy ate his whole bowl of kibble in ten seconds.","strategyClue":"Look at the question's key words, then scan the passage for a sentence that lists specific examples or measurements that match those key words.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They measured rainfall, wind direction, temperature, and cloud cover every day. This sentence lists four distinct types of data the students recorded, which provides clear, factual support that they were tracking multiple forms of weather evidence.","incorrect":["",{"choice":"The music teacher tuned a violin before class.","category":"irrelevant information","reason":"This detail describes a music class and has nothing to do with weather science or the students' data collection process."},{"choice":"The passage says every reader already knew about weather station.","category":"unsupported claim","reason":"The passage does not state that readers already knew about weather stations, and this idea does not prove that students collected multiple types of data."},{"choice":"The title names the topic but gives no proof.","category":"missing evidence","reason":"A title might introduce a subject, but it does not contain specific facts or measurements that demonstrate the variety of data the students gathered."}]},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":40,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0041","version":3,"contentHash":"sha256:9efe0879200074b9d747f3324d8e7cd0345b79adef586f8b6f9c82a80fec35e2","question":"Read the passage. Grade 2 challenge passage: A recycling team reduced paper waste at school. They placed blue bins in classrooms and reminded students to use both sides of paper. By winter break, the school ordered fewer boxes of printer paper. Because the passage connects actions with results, readers can see why the recycling team helped the school waste less paper.\n\nWhich sentence from the passage best supports this idea: The plan changed how much paper the school used.","choices":["The nurse checked the first-aid supplies after lunch.","By winter break, the school ordered fewer boxes of printer paper.","The passage says every reader already knew about recycling team.","The title names the topic but gives no proof."],"correct":1,"studyAid":{"definition":"To find evidence in a text, look for facts or data that prove a specific claim or statement is true.","example":"Claim: 'It rained hard.' Evidence: 'The gutters were overflowing and the street was flooded.'","strategyClue":"Look for the sentence that provides a measurement or result showing a change in the quantity of paper the school consumed.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: By winter break, the school ordered fewer boxes of printer paper. This sentence shows the direct result of the recycling team's actions, proving the amount of paper used at the school actually decreased.","incorrect":[{"choice":"The nurse checked the first-aid supplies after lunch.","category":"irrelevant information","reason":"This sentence mentions a nurse and first-aid supplies, which are not related to the recycling team or the use of printer paper."},"",{"choice":"The passage says every reader already knew about recycling team.","category":"incorrect text evidence","reason":"The passage does not state that readers already knew about the team; furthermore, this claim does not provide evidence for the school changing how much paper it used."},{"choice":"The title names the topic but gives no proof.","category":"lacks supporting evidence","reason":"While a title might name a topic, it does not act as evidence to show how much paper the school used or how that amount changed over time."}]},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":41,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0042","version":3,"contentHash":"sha256:02aecb52aded241cfc2a66f75644ca95bbe8698b98aad1d36d1c6b04010dc2a1","question":"Read the passage. Grade 2 challenge passage: Museum workers built an exhibit about local history. They displayed old tools, photographs, letters, and a map of the first town road. Visitors could press buttons to hear recordings of elders telling memories. Because the passage connects actions with results, readers can see why the exhibit used artifacts and voices to teach local history.\n\nWhich detail is the strongest evidence for the answer, \"The exhibit included both objects and personal stories.\"?","choices":["The passage says every reader already knew about museum exhibit.","A rainstorm delayed the baseball game.","Visitors could press buttons to hear recordings of elders telling memories.","The title names the topic but gives no proof."],"correct":2,"studyAid":{"definition":"Evidence is a specific detail from a text that proves a statement is true. Strong evidence must directly relate to the ideas in the prompt.","example":"Statement: 'The weather is cold.' Evidence: 'I can see my breath in the air.' (vs. 'I like to play outside.')","strategyClue":"Break your target statement into two parts: objects and personal stories. Scan the text for nouns that fit these two categories and select the sentence that mentions both.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Visitors could press buttons to hear recordings of elders telling memories. This sentence specifically mentions the 'recordings of elders' (personal stories) and the tools/map (objects), proving the exhibit contained both types of information.","incorrect":[{"choice":"The passage says every reader already knew about museum exhibit.","category":"unsupported claim","reason":"The passage never states that readers knew about the exhibit, nor does this idea provide evidence for what the exhibit included."},{"choice":"A rainstorm delayed the baseball game.","category":"irrelevant information","reason":"This detail is not mentioned in the passage and has nothing to do with museum exhibits, objects, or personal stories."},"",{"choice":"The title names the topic but gives no proof.","category":"missing textual evidence","reason":"This does not act as evidence; it describes a potential problem with the text rather than providing the proof needed to confirm the exhibit's contents."}]},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":42,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0043","version":3,"contentHash":"sha256:793fed3c1eba9f5265ed7cc0a26386023145eddefd47f3374eeb7435b3f7f9f1","question":"Read the passage. Grade 2 challenge passage: Club members improved a robot through testing. Each time the robot missed a turn, members adjusted the code and tested again. They kept notes about which wheel speed worked best on the course. Because the passage connects actions with results, readers can see why testing and revising helped the robotics club improve its robot.\n\nWhich sentence from the passage best supports this idea: The club used mistakes as information.","choices":["The title names the topic but gives no proof.","The principal announced picture day over the speaker.","The passage says every reader already knew about robotics club.","Each time the robot missed a turn, members adjusted the code and tested again."],"correct":3,"studyAid":{"definition":"To find text evidence, look for sentences that show cause and effect, where an action or discovery directly results from a previous attempt.","example":"Mistake: I tripped. Information: I learned to lift my feet higher. Result: I didn't trip again.","strategyClue":"Look for the specific sentence where the team encounters a problem or a failure and then immediately takes a step to fix it.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Each time the robot missed a turn, members adjusted the code and tested again. This sentence shows that when the robot failed (a mistake), the club used that feedback to change the code (information).","incorrect":[{"choice":"The title names the topic but gives no proof.","category":"not in text","reason":"This sentence does not appear in the passage and does not describe how the club learned from errors."},{"choice":"The principal announced picture day over the speaker.","category":"irrelevant information","reason":"This information is not related to the robotics club or the process of testing and revising."},{"choice":"The passage says every reader already knew about robotics club.","category":"unsupported claim","reason":"The passage never mentions what the readers knew; it focuses on the actions taken by the club members."},""]},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":43,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0044","version":3,"contentHash":"sha256:62bc02d675b34522ffbdd97fa46ecadb1b13fa5d062dd09f6d1f67566db4145a","question":"Read the passage. Grade 2 challenge passage: School leaders started a breakfast cart. The cart offered fruit, yogurt, and whole-grain muffins near the front door. Students who arrived close to the bell could still choose a quick meal. Because the passage connects actions with results, readers can see why the breakfast cart helped more students start the day with food.\n\nWhich detail is the strongest evidence for the answer, \"The cart was designed for students with little time before class.\"?","choices":["Students who arrived close to the bell could still choose a quick meal.","The science lab received new magnifying glasses.","The passage says every reader already knew about school breakfast.","The title names the topic but gives no proof."],"correct":0,"studyAid":{"definition":"Strong evidence is a specific fact or detail from the text that directly proves or explains the main idea or a claim.","example":"Claim: The park is popular. Evidence: Every bench was taken by people enjoying the sun.","strategyClue":"Highlight the claim in the question, then look for the specific sentence in the text that shows the 'why' or 'how' behind that claim.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Students who arrived close to the bell could still choose a quick meal. This detail directly supports the claim that the cart was designed for time-crunched students because 'arriving close to the bell' indicates limited time, and a 'quick meal' addresses that specific need.","incorrect":["",{"choice":"The science lab received new magnifying glasses.","category":"irrelevant information","reason":"This sentence mentions science equipment, which is completely unrelated to the breakfast cart or student breakfast habits."},{"choice":"The passage says every reader already knew about school breakfast.","category":"unsupported claim","reason":"The passage does not state this, and even if it did, a reader's background knowledge is not evidence of the cart's design purpose."},{"choice":"The title names the topic but gives no proof.","category":"missing supporting evidence","reason":"Titles act as labels, not evidence. A title cannot explain the reason behind the cart's design or how it helps students."}]},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":44,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0045","version":3,"contentHash":"sha256:ed05690e6ce68e536878c945714323ba540ef019d43163e4cb86d59a7b15f8d1","question":"Read the passage. Grade 2 challenge passage: Park rangers marked a trail for visitors. They added arrows, distance signs, and small plaques naming common trees. A new bench gave hikers a place to rest near the creek. Because the passage connects actions with results, readers can see why trail signs helped visitors move safely and learn about nature.\n\nWhich sentence from the passage best supports this idea: The signs gave visitors both directions and information.","choices":["The post office closed early on Saturday.","They added arrows, distance signs, and small plaques naming common trees.","The passage says every reader already knew about nature trail.","The title names the topic but gives no proof."],"correct":1,"studyAid":{"definition":"To support an idea, look for evidence in the text that directly matches the specific details mentioned in your claim.","example":"Claim: The classroom was messy. Evidence: Papers were scattered on the floor and crayons were left under the desks.","strategyClue":"Look for keywords from the claim—in this case, 'directions' and 'information'—and scan the text to find which sentence lists items that match those two categories.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They added arrows, distance signs, and small plaques naming common trees. This sentence directly provides evidence of 'arrows' (directions) and 'plaques naming trees' (information), supporting the idea that signs provided both.","incorrect":[{"choice":"The post office closed early on Saturday.","category":"irrelevant information","reason":"This sentence is not found in the passage and has nothing to do with trail signs, directions, or learning about nature."},"",{"choice":"The passage says every reader already knew about nature trail.","category":"incorrect text evidence","reason":"The passage never states that readers already knew about the trail; instead, it explains how the signs helped visitors who were using the trail."},{"choice":"The title names the topic but gives no proof.","category":"missing textual support","reason":"The question asks for a sentence from the passage that proves the idea. This statement describes a title, which does not contain the specific details about signs found in the text."}]},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":45,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0046","version":3,"contentHash":"sha256:b4d40bc006c264bf620a737b6789300cc8c7c801c94ed97a841d1fc0c357e52c","question":"Read the passage. Grade 3 foundation passage: A class kept a school garden healthy. Students watered the seedlings each morning and recorded how tall they grew. They also moved the shade cloth when the afternoon sun became too strong.\n\nWhich sentence from the passage best supports this idea: The students used observations to care for the plants.","choices":["The passage says every reader already knew about school garden.","The art room displayed clay bowls near the window.","They recorded how tall the seedlings grew.","The title names the topic but gives no proof."],"correct":2,"studyAid":{"definition":"To support an idea, you must find a specific detail in the text that provides evidence or proof for the claim.","example":"Claim: The dog is energetic. Supporting evidence: The dog ran in circles and jumped over the couch.","strategyClue":"Identify the key action mentioned in the claim ('used observations'), then look for a sentence that describes that specific type of action taking place in the story.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They recorded how tall the seedlings grew. To 'use observations' means to look closely and track changes. Recording the height of the plants is a direct example of observing and tracking their growth over time.","incorrect":[{"choice":"The passage says every reader already knew about school garden.","category":"Unsupported claim","reason":"This statement is not found in the text, nor does it provide evidence of students using observations to care for the garden."},{"choice":"The art room displayed clay bowls near the window.","category":"Irrelevant information","reason":"This sentence describes art supplies, not the school garden or any plant-care activities, so it does not support the idea."},"",{"choice":"The title names the topic but gives no proof.","category":"Meta-commentary error","reason":"The question asks for a sentence that proves the students used observations; a sentence about a title does not contain any evidence about plant care."}]},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":46,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0047","version":3,"contentHash":"sha256:627682d3871eaa0c8946d89129fe080842fa3081dc04dea10328140740c94b60","question":"Read the passage. Grade 3 foundation passage: Student volunteers made the library easier to use. They sorted returned books by call number before placing them on shelves. They made bright shelf labels for mystery, science, and biography books.\n\nWhich detail is the strongest evidence for the answer, \"The volunteers helped readers find materials more efficiently.\"?","choices":["The title names the topic but gives no proof.","The cafeteria served tomato soup on Thursday.","The passage says every reader already knew about library helpers.","They sorted returned books by call number before placing them on shelves."],"correct":3,"studyAid":{"definition":"To find the strongest evidence, look for a sentence that directly explains the 'how' or 'why' behind the main claim.","example":"Claim: The classroom is clean. Evidence: The students recycled all the scrap paper and wiped down the desks.","strategyClue":"Ask yourself which choice describes a specific action the volunteers took to organize or improve the library's system. Ignore statements that are about a different topic or that do not explain a change in efficiency.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They sorted returned books by call number before placing them on shelves. This action directly explains how materials were organized, which makes it faster and easier for readers to locate specific items.","incorrect":[{"choice":"The title names the topic but gives no proof.","category":"irrelevant to evidence","reason":"Titles only introduce a subject; they do not provide specific actions or evidence showing how volunteers made the library more efficient."},{"choice":"The cafeteria served tomato soup on Thursday.","category":"unrelated topic","reason":"This information is about the cafeteria, not the library. It does not provide any evidence for how the volunteers helped in the library."},{"choice":"The passage says every reader already knew about library helpers.","category":"inaccurate content","reason":"The passage does not state that readers already knew about the helpers, and even if it did, knowing about helpers is not the same as the books being organized efficiently."},""]},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":47,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0048","version":3,"contentHash":"sha256:d4a3c429eecacb2d1ad81224c6c69b95c3ff27d2f031ae2768c9b61155529e3b","question":"Read the passage. Grade 3 foundation passage: A science club collected rainwater for outdoor plants. The barrel caught water from the roof during storms. Members used the stored water on dry afternoons instead of turning on the hose.\n\nWhich sentence from the passage best supports this idea: The rain barrel reduced the need for hose water.","choices":["Members used the stored water on dry afternoons instead of turning on the hose.","A soccer team practiced corner kicks after school.","The passage says every reader already knew about rain barrel.","The title names the topic but gives no proof."],"correct":0,"studyAid":{"definition":"To support an idea, find a sentence that describes a specific action or fact that proves the idea is true.","example":"Idea: The puppy was hungry. Evidence: The puppy whined and stared at his empty bowl.","strategyClue":"Look for the keywords from the idea (like 'hose' or 'water') in the passage. Find the sentence that describes what happened to those things to see if it matches the main point.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Members used the stored water on dry afternoons instead of turning on the hose. This sentence directly describes the action of using collected rain instead of the hose, which is exactly what 'reduced the need for hose water' means.","incorrect":["",{"choice":"A soccer team practiced corner kicks after school.","category":"irrelevant information","reason":"This sentence is not about science or rainwater, and it does not appear anywhere in the provided passage."},{"choice":"The passage says every reader already knew about rain barrel.","category":"unsupported claim","reason":"The text does not mention what the reader already knows; it only explains how the club used the barrel."},{"choice":"The title names the topic but gives no proof.","category":"incorrect logic","reason":"The passage provides specific evidence of the club's actions; this choice ignores the actual content of the story."}]},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":48,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0049","version":3,"contentHash":"sha256:03f4ecd907d3da6157a2078c0018323e9e1e344481c09b84605e4f86b732ebfe","question":"Read the passage. Grade 3 foundation passage: Young reporters created a newspaper for their school. They interviewed teachers, wrote short articles, and checked facts before printing. The first issue included a sports column, a book review, and a lunch survey.\n\nWhich detail is the strongest evidence for the answer, \"The reporters tried to make the newspaper accurate.\"?","choices":["The playground slide was painted blue over spring break.","They interviewed teachers, wrote short articles, and checked facts before printing.","The passage says every reader already knew about class newspaper.","The title names the topic but gives no proof."],"correct":1,"studyAid":{"definition":"To find evidence for a claim, look for specific actions or descriptions in the text that directly support the idea mentioned in the question.","example":"Claim: The chef worked carefully. Evidence: The chef measured every ingredient and timed the baking perfectly.","strategyClue":"Look at the key word in the claim (in this case, 'accurate') and scan the text for verbs or actions that match that concept, such as checking, verifying, or researching.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They interviewed teachers, wrote short articles, and checked facts before printing. Checking facts is the direct action of verifying information to ensure it is true and correct, which is the definition of accuracy.","incorrect":[{"choice":"The playground slide was painted blue over spring break.","category":"irrelevant information","reason":"This detail describes school property, not the activities the reporters performed to verify their newspaper content."},"",{"choice":"The passage says every reader already knew about class newspaper.","category":"factually unsupported","reason":"The text does not mention the readers' prior knowledge; this is an assumption that does not prove the reporters worked to be accurate."},{"choice":"The title names the topic but gives no proof.","category":"missing evidence","reason":"A title is just a label for the story; it does not contain the specific actions required to show that the reporters were careful about accuracy."}]},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":49,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0050","version":3,"contentHash":"sha256:a938ec623269f9eceff0881c80d0e5f0a3b587a3460b7b903fe2765dde824bc5","question":"Read the passage. Grade 3 foundation passage: Families removed litter from the beach. They filled ten bags with plastic wrappers, bottle caps, and broken fishing line. Afterward, volunteers posted signs reminding visitors to pack out trash.\n\nWhich sentence from the passage best supports this idea: The cleanup made the beach safer for wildlife.","choices":["The passage says every reader already knew about beach cleanup.","The town band played a concert in the park.","They filled ten bags with plastic wrappers, bottle caps, and broken fishing line.","The title names the topic but gives no proof."],"correct":2,"studyAid":{"definition":"Supporting details are facts, examples, or descriptions that prove or explain a main idea.","example":"Main idea: 'Dogs are helpful animals.' Supporting detail: 'They can be trained to guide people who cannot see.'","strategyClue":"Look for specific items or actions in the text that directly relate to the keywords in your goal, such as 'trash' or 'wildlife' risks.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They filled ten bags with plastic wrappers, bottle caps, and broken fishing line. This sentence provides evidence of the cleanup, showing the removal of items like plastic and fishing line that can be harmful or dangerous to wild animals.","incorrect":[{"choice":"The passage says every reader already knew about beach cleanup.","category":"unsupported text claim","reason":"This information is not found in the passage, and even if it were, it does not explain why the beach is safer for wildlife."},{"choice":"The town band played a concert in the park.","category":"irrelevant information","reason":"This sentence mentions a band and a park, which has nothing to do with the beach or the safety of wildlife."},"",{"choice":"The title names the topic but gives no proof.","category":"misunderstanding evidence","reason":"A title might introduce a subject, but it does not provide the details needed to prove that the beach became safer for animals."}]},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":50,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}}],"metadata":{"gradesSupported":[3,4,5,6],"difficultiesSupported":["easy","medium","hard"],"selectorPolicy":"grade+difficulty selects exact matches first, with 15 exact-match questions for every supported grade and difficulty"}};
  const bank = window.QUESTION_BANK = window.QUESTION_BANK || {};
  const existing = bank["reading-comprehension-text-evidence"];
  if (existing && Array.isArray(existing.questions)) {
    const seen = new Set(existing.questions.map(question => question && question.id));
    chunkSet.questions.forEach(question => {
      if (!seen.has(question && question.id)) existing.questions.push(question);
    });
  } else {
    bank["reading-comprehension-text-evidence"] = chunkSet;
  }
})();
